DEFAULT_COMMAND_PREFIXES = (
    ("python", "-m", "pytest"),
    ("python", "-m", "py_compile"),
    ("python", "-m", "compileall"),
    ("python3", "-m", "pytest"),
    ("python3", "-m", "py_compile"),
